import AVFoundation
import Combine

// MARK: - Audio Capture Error

enum AudioCaptureError: Error, Equatable {
    case permissionDenied
    case engineStartFailed(String)
    case converterSetupFailed
}

// MARK: - Audio Segment

/// A segment of 16kHz mono PCM audio ready for transcription
struct AudioSegment {
    let samples: [Float]        // 16kHz mono float32
    let capturedAt: Date
}

// MARK: - Audio Capture Service (Tasks 4.1 - 4.6)

final class AudioCaptureService {

    /// Emits completed audio segments (post-VAD silence detection)
    let audioSegmentPublisher = PassthroughSubject<AudioSegment, Never>()
    /// Emits current RMS level 0..1 for waveform display
    let levelPublisher = PassthroughSubject<Float, Never>()
    /// 录音会话结束时发出，携带本次会话完整音频和时间边界
    let sessionEndPublisher = PassthroughSubject<RecordingSessionData, Never>()

    /// 当前录音会话累积的 PCM 样本（所有 VAD 段依次追加）
    private var sessionSamples: [Float] = []

    private let engine = AVAudioEngine()
    private var converter: AVAudioConverter?
    private let ringBuffer = AudioRingBuffer()           // 30min capacity
    private let vadDetector = VADDetector()
    private var sessionStartedAt: Date?

    private weak var appState: AppState?
    private var cancellables = Set<AnyCancellable>()

    // Whisper requires 16kHz mono
    private let targetFormat = AVAudioFormat(
        commonFormat: .pcmFormatFloat32,
        sampleRate: 16000,
        channels: 1,
        interleaved: false
    )!

import Foundation
import Combine

// MARK: - Recording Source

enum RecordingSource: String, CaseIterable, Identifiable {
    case microphone = "microphone"
    case bluetoothRecorder = "bluetoothRecorder"

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .microphone: return "麦克风"
        case .bluetoothRecorder: return "蓝牙录音笔"
        }
    }
}

enum SpeechPipelineMode: String, CaseIterable, Identifiable {
    case legacyWhisperCPP = "legacyWhisperCPP"
    case experimentalArgmaxOSS = "experimentalArgmaxOSS"

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .legacyWhisperCPP: return "whisper.cpp + FluidAudio"
        case .experimentalArgmaxOSS: return "WhisperKit + SpeakerKit (Experimental)"
        }
    }
}

// MARK: - Recording State

enum RecordingState: Equatable {
    case idle
    case recording(startedAt: Date)
    case processing

    var isRecording: Bool {
        if case .recording = self { return true }
        return false
    }

    var duration: TimeInterval? {
        guard case .recording(let start) = self else { return nil }
        return Date().timeIntervalSince(start)
    }
}

// MARK: - Transcription Entry

struct TranscriptionEntry: Identifiable, Equatable {
    let id = UUID()
    let text: String
    let timestamp: Date
    let duration: TimeInterval // audio segment duration in seconds

    var formattedTimestamp: String {
        let f = DateFormatter()
        f.timeStyle = .medium
        f.dateStyle = .none
        return f.string(from: timestamp)
    }
}

// MARK: - App State (Task 2.3)

@MainActor
final class AppState: ObservableObject {
    // Recording
    @Published var recordingState: RecordingState = .idle
    @Published var audioLevel: Float = 0.0          // 0.0 - 1.0 for waveform
    @Published var bufferWarning: Bool = false       // ring buffer overflow warning

    // Transcription
    @Published var entries: [TranscriptionEntry] = []
    @Published var realtimeChunks: [RealtimeTranscriptChunk] = []
    @Published var isModelLoaded: Bool = false
    @Published var modelLoadError: String? = nil

    // WhisperKit 模型状态（实验性模式专用）
    @Published var isWhisperKitModelReady: Bool = false
    @Published var whisperKitModelStatus: String = "正在准备 WhisperKit 模型..."

    // Errors
    @Published var micPermissionDenied: Bool = false
    @Published var accessibilityPermissionGranted: Bool = false

    // BLE 录音笔
    @Published var recordingSource: RecordingSource {
        didSet { UserDefaults.standard.set(recordingSource.rawValue, forKey: "recordingSource") }
    }
    @Published var bleConnectionState: BLEConnectionState = .disconnected
    @Published var bleBatteryLevel: Int? = nil      // 0-100, 110=充电中
    @Published var bleDeviceStatus: BLEDeviceStatus = []

    // 历史录音（由 RecordingFileService 驱动）
    var recordingFileService: RecordingFileService?
    /// 当前正在播放的录音 ID（nil 表示无播放）
    @Published var currentlyPlayingId: UUID? = nil

    // Preferences
    @Published var selectedModel: WhisperModel {
        didSet { UserDefaults.standard.set(selectedModel.rawValue, forKey: "selectedModel") }
    }
    @Published var speechPipelineMode: SpeechPipelineMode {
        didSet { UserDefaults.standard.set(speechPipelineMode.rawValue, forKey: "speechPipelineMode") }
    }
    @Published var vadSilenceThresholdMs: Int = 500

    // E2E 测试钩子：由 AppDelegate 注入，供 SwiftUI 按钮调用
    var toggleRecordingAction: (() -> Void)?
    // 偏好设置入口：由 AppDelegate 注入，StatusBarManager 和 TranscriptionPopoverView 统一调用
    var openPreferencesAction: (() -> Void)?

    init() {
        let stored = UserDefaults.standard.string(forKey: "selectedModel")
        selectedModel = stored.flatMap(WhisperModel.init(rawValue:)) ?? .tiny

        let storedPipeline = UserDefaults.standard.string(forKey: "speechPipelineMode")
        speechPipelineMode = storedPipeline.flatMap(SpeechPipelineMode.init(rawValue:)) ?? .legacyWhisperCPP

        let storedSource = UserDefaults.standard.string(forKey: "recordingSource")
        recordingSource = storedSource.flatMap(RecordingSource.init(rawValue:)) ?? .microphone
    }

    // MARK: Computed

    var allTranscriptionText: String {
        entries.map(\.text).joined(separator: "\n")
    }

    var recordingDuration: TimeInterval {
        recordingState.duration ?? 0
    }

    // MARK: Mutations

    func appendEntry(_ entry: TranscriptionEntry) {
        entries.append(entry)
    }

    func updateRealtimeChunks(_ chunks: [RealtimeTranscriptChunk]) {
        realtimeChunks = chunks
    }

    func clearSession() {
        entries.removeAll()
        realtimeChunks.removeAll()
    }

    func startRecording() {
        recordingState = .recording(startedAt: Date())
    }

    func stopRecording() {
        recordingState = .idle
        audioLevel = 0
    }
}

// MARK: - Whisper Model

enum WhisperModel: String, CaseIterable, Identifiable {
    case tiny             = "ggml-tiny"
    case base             = "ggml-base"
    case small            = "ggml-small"
    case medium           = "ggml-medium"
    case largeV2          = "ggml-large-v2"
    case largeV3          = "ggml-large-v3"
    case largeV3Q5_0      = "ggml-large-v3-q5_0"
    case largeV3TurboQ5_0 = "ggml-large-v3-turbo-q5_0"

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .tiny:             return "Tiny (~75 MB)"
        case .base:             return "Base (~142 MB)"
        case .small:            return "Small (~244 MB)"
        case .medium:           return "Medium (~769 MB)"
        case .largeV2:          return "Large v2 (~2.87 GB)"
        case .largeV3:          return "Large v3 (~2.87 GB)"
        case .largeV3Q5_0:      return "Large v3 Q5_0 (~1.1 GB)"
        case .largeV3TurboQ5_0: return "Large v3 Turbo Q5_0 (~0.6 GB)"
        }
    }

    /// 量化模型标记，在 UI 中显示"推荐"标签
    var isRecommended: Bool {
        switch self {
        case .largeV3Q5_0, .largeV3TurboQ5_0: return true
        default: return false
        }
    }

    var filename: String { "\(rawValue).bin" }

    /// Hugging Face / ggerganov CDN download URL
    var downloadURL: URL {
        URL(string: "https://huggingface.co/ggerganov/whisper.cpp/resolve/main/\(filename)")!
    }
}

import SwiftUI

// MARK: - Transcription List

struct TranscriptionListView: View {
    @EnvironmentObject var appState: AppState

    var body: some View {
        Group {
            if appState.speechPipelineMode == .experimentalArgmaxOSS {
                RealtimeChunkListView()
                    .environmentObject(appState)
            } else {
                LegacyEntryListView()
                    .environmentObject(appState)
            }
        }
    }
}

// MARK: - Legacy Entry List (whisper.cpp 模式)

private struct LegacyEntryListView: View {
    @EnvironmentObject var appState: AppState

    var body: some View {
        Group {
            if appState.entries.isEmpty {
                EmptyTranscriptionView()
            } else {
                ScrollViewReader { proxy in
                    ScrollView {
                        LazyVStack(alignment: .leading, spacing: 8) {
                            ForEach(appState.entries) { entry in
                                EntryRow(entry: entry)
                                    .id(entry.id)
                                    .accessibilityIdentifier("transcriptionEntry-\(entry.id)")
                            }
                        }
                        .padding(.horizontal, 16)
                        .padding(.vertical, 8)
                    }
                    .accessibilityIdentifier("transcriptionScrollView")
                    .onChange(of: appState.entries.count) {
                        if let lastId = appState.entries.last?.id {
                            withAnimation(.easeOut(duration: 0.2)) {
                                proxy.scrollTo(lastId, anchor: .bottom)
                            }
                        }
                    }
                }
            }
        }
    }
}

// MARK: - Realtime Chunk List (实验性模式)

private struct RealtimeChunkListView: View {
    @EnvironmentObject var appState: AppState

    var body: some View {
        Group {
            if appState.realtimeChunks.isEmpty {
                EmptyTranscriptionView()
            } else {
                ScrollViewReader { proxy in
                    ScrollView {
                        LazyVStack(alignment: .leading, spacing: 8) {
                            ForEach(appState.realtimeChunks) { chunk in
                                ChunkRowView(chunk: chunk)
                                    .id(chunk.id)
                                    .accessibilityIdentifier("transcriptionEntry-\(chunk.id)")
                            }
                        }
                        .padding(.horizontal, 16)
                        .padding(.vertical, 8)
                    }
                    .accessibilityIdentifier("transcriptionScrollView")
                    .onChange(of: appState.realtimeChunks.count) {
                        if let lastId = appState.realtimeChunks.last?.id {
                            withAnimation(.easeOut(duration: 0.2)) {
                                proxy.scrollTo(lastId, anchor: .bottom)
                            }
                        }
                    }
                }
            }
        }
    }
}

// MARK: - Chunk Row (实验性模式带 speaker badge)

struct ChunkRowView: View {
    let chunk: RealtimeTranscriptChunk

    var body: some View {
        HStack(alignment: .top, spacing: 8) {
            Text(chunk.speakerLabel ?? "?")
                .font(.caption2)
                .fontWeight(.semibold)
                .foregroundColor(.white)
                .padding(.horizontal, 5)
                .padding(.vertical, 2)
                .background(speakerColor)
                .cornerRadius(4)
                .fixedSize()

            VStack(alignment: .leading, spacing: 2) {
                Text(chunk.text)
                    .font(.body)
                    .textSelection(.enabled)
                    .fixedSize(horizontal: false, vertical: true)
                    .foregroundColor(chunk.isFinal ? .primary : .secondary)

                Text(String(format: "%.1fs – %.1fs", chunk.startTimeSeconds, chunk.endTimeSeconds))
                    .font(.caption2)
                    .foregroundColor(.secondary)
            }
        }
        .padding(8)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(Color(NSColor.controlBackgroundColor))
        .cornerRadius(6)
    }

    private var speakerColor: Color {
        switch chunk.speakerLabel {
        case "S0": return .blue
        case "S1": return Color.orange
        case "S2": return Color.purple
        case "S3": return Color.green
        case "S4": return Color.pink
        case nil:  return Color.gray
        default:   return Color.indigo
        }
    }
}

// MARK: - Entry Row (Legacy)

private struct EntryRow: View {
    let entry: TranscriptionEntry

    var body: some View {
        VStack(alignment: .leading, spacing: 2) {
            Text(entry.text)
                .font(.body)
                .textSelection(.enabled)
                .fixedSize(horizontal: false, vertical: true)

            Text(entry.formattedTimestamp)
                .font(.caption2)
                .foregroundColor(.secondary)
        }
        .padding(8)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(Color(NSColor.controlBackgroundColor))
        .cornerRadius(6)
    }
}

// MARK: - Empty State

struct EmptyTranscriptionView: View {
    @EnvironmentObject var appState: AppState

    var body: some View {
        VStack(spacing: 12) {
            Image(systemName: "mic.slash")
                .font(.system(size: 32))
                .foregroundColor(.secondary)
                .accessibilityIdentifier("emptyStateIcon")

            if let error = appState.modelLoadError {
                Text("模型加载失败")
                    .font(.headline)
                Text(error)
                    .font(.caption)
                    .foregroundColor(.red)
                    .multilineTextAlignment(.center)
            } else if appState.speechPipelineMode == .experimentalArgmaxOSS && !appState.isWhisperKitModelReady {
                Text(appState.whisperKitModelStatus)
                    .font(.callout)
                    .foregroundColor(.secondary)
                    .multilineTextAlignment(.center)
                ProgressView()
                    .scaleEffect(0.8)
            } else if !appState.isModelLoaded {
                Text("正在加载 Whisper 模型...")
                    .font(.callout)
                    .foregroundColor(.secondary)
                ProgressView()
                    .scaleEffect(0.8)
            } else if appState.micPermissionDenied {
                Text("麦克风权限被拒绝")
                    .font(.headline)
                Text("请在系统设置 > 隐私与安全 > 麦克风 中允许 VoicePepper")
                    .font(.caption)
                    .foregroundColor(.secondary)
                    .multilineTextAlignment(.center)
            } else {
                Text("按下快捷键开始录音")
                    .font(.callout)
                    .foregroundColor(.secondary)

                Text("默认：⌥ Space")
                    .font(.caption)
                    .foregroundColor(.secondary)
                    .padding(4)
                    .background(Color(NSColor.controlBackgroundColor))
                    .cornerRadius(4)
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .padding()
        .accessibilityIdentifier("emptyTranscriptionView")
    }
}

