3	actor TimelineMerger {
4	    private var chunks: [RealtimeTranscriptChunk] = []
5	    private var speakerEvents: [SpeakerSegmentEvent] = []
6	
7	    func applyASREvent(
8	        _ event: ASRTranscriptEvent,
9	        source: RecordingSource
10	    ) -> [RealtimeTranscriptChunk] {
11	        let matchingSpeaker = bestSpeakerEvent(
12	            forStart: event.startTimeSeconds,
13	            end: event.endTimeSeconds
14	        )
15	
16	        if let index = chunks.firstIndex(where: { $0.id == event.id }) {
17	            chunks[index].startTimeSeconds = event.startTimeSeconds
18	            chunks[index].endTimeSeconds = event.endTimeSeconds
19	            chunks[index].text = event.text
20	            chunks[index].isFinal = event.isFinal
21	            chunks[index].speakerLabel = matchingSpeaker?.speakerLabel
22	            chunks[index].speakerConfidence = matchingSpeaker?.confidence
23	        } else {
24	            chunks.append(
25	                RealtimeTranscriptChunk(
26	                    id: event.id,
27	                    startTimeSeconds: event.startTimeSeconds,
28	                    endTimeSeconds: event.endTimeSeconds,
29	                    text: event.text,
30	                    isFinal: event.isFinal,
31	                    speakerLabel: matchingSpeaker?.speakerLabel,
32	                    speakerConfidence: matchingSpeaker?.confidence,
33	                    source: source
34	                )
35	            )
36	        }
37	
38	        chunks.sort { $0.startTimeSeconds < $1.startTimeSeconds }
39	        return chunks
40	    }
41	
42	    func applySpeakerEvent(_ event: SpeakerSegmentEvent) -> [RealtimeTranscriptChunk] {
43	        if !speakerEvents.contains(where: { $0.id == event.id }) {
44	            speakerEvents.append(event)
45	        }
46	
47	        for index in chunks.indices {
48	            let chunk = chunks[index]
49	            if let bestMatch = bestSpeakerEvent(forStart: chunk.startTimeSeconds, end: chunk.endTimeSeconds) {
50	                chunks[index].speakerLabel = bestMatch.speakerLabel
51	                chunks[index].speakerConfidence = bestMatch.confidence
52	            }
53	        }
54	
55	        return chunks
56	    }
57	
58	    func snapshot() -> [RealtimeTranscriptChunk] {
59	        chunks
60	    }
61	
62	    private func bestSpeakerEvent(forStart start: Double, end: Double) -> SpeakerSegmentEvent? {
63	        let overlapping = speakerEvents
64	            .map { event in (event, overlapDuration(startA: start, endA: end, startB: event.startTimeSeconds, endB: event.endTimeSeconds)) }
65	            .filter { $0.1 > 0 }
66	            .sorted { $0.1 > $1.1 }
67	
68	        if let best = overlapping.first?.0 {
69	            return best
70	        }
71	
72	        let midpoint = (start + end) / 2
73	        return speakerEvents.min {
74	            distance(midpoint, to: $0) < distance(midpoint, to: $1)
75	        }
