3	
4	final class AudioFileSource {
5	    let audioSegmentPublisher = PassthroughSubject<AudioSegment, Never>()
6	    let sessionEndPublisher = PassthroughSubject<RecordingSessionData, Never>()
7	
8	    private var isStopped = false
9	
10	    func play(url: URL, chunkDuration: TimeInterval = 1.5) async {
11	        isStopped = false
12	        let startedAt = Date()
13	
14	        let audioFile: AVAudioFile
15	        do {
16	            audioFile = try AVAudioFile(forReading: url)
17	        } catch {
18	            NSLog("[AudioFileSource] 无法读取文件: %@ error=%@", url.path, error.localizedDescription)
19	            return
20	        }
21	
22	        let format = audioFile.processingFormat
23	        guard format.sampleRate == 16000, format.channelCount == 1 else {
24	            NSLog("[AudioFileSource] 格式不符: sampleRate=%.0f channels=%d (需要 16kHz mono)",
25	                  format.sampleRate, format.channelCount)
26	            sessionEndPublisher.send(RecordingSessionData(samples: [], startedAt: startedAt, endedAt: Date()))
27	            return
28	        }
29	
30	        let samplesPerChunk = AVAudioFrameCount(format.sampleRate * chunkDuration)
31	        var allSamples: [Float] = []
32	
33	        while !isStopped {
34	            guard let buffer = AVAudioPCMBuffer(pcmFormat: format, frameCapacity: samplesPerChunk) else { break }
35	
36	            do {
37	                try audioFile.read(into: buffer, frameCount: samplesPerChunk)
38	            } catch {
39	                break
40	            }
41	
42	            guard buffer.frameLength > 0, let channelData = buffer.floatChannelData else { break }
43	
44	            let samples = Array(UnsafeBufferPointer(start: channelData[0], count: Int(buffer.frameLength)))
45	            allSamples.append(contentsOf: samples)
46	            audioSegmentPublisher.send(AudioSegment(samples: samples, capturedAt: Date()))
47	
48	            // pace to real-time to avoid CPU burst
49	            let ns = UInt64(Double(buffer.frameLength) / format.sampleRate * 1_000_000_000)
50	            try? await Task.sleep(nanoseconds: ns)
51	        }
52	
53	        guard !isStopped else { return }
54	        sessionEndPublisher.send(RecordingSessionData(samples: allSamples, startedAt: startedAt, endedAt: Date()))
55	    }
