404	        // 评估流水线通过 `defaults write` 注入路径，需在启动时同步最新值
405	        UserDefaults.standard.synchronize()
406	        if let path = UserDefaults.standard.string(forKey: "filePlaybackWAVPath"), !path.isEmpty {
407	            appState.filePlaybackWAVURL = URL(fileURLWithPath: path)
408	        }
409	        guard let url = appState.filePlaybackWAVURL else {
410	            NSLog("[AppDelegate] filePlayback: 未选择 WAV 文件，请在偏好设置中选择")
411	            return
