import AVFoundation
import Combine

// MARK: - Audio Capture Error

enum AudioCaptureError: Error, Equatable {
    case permissionDenied
    case engineStartFailed(String)
    case converterSetupFailed
}

// MARK: - Audio Segment

/// A segment of 16kHz mono PCM audio ready for transcription
struct AudioSegment {
    let samples: [Float]        // 16kHz mono float32
    let capturedAt: Date
}

// MARK: - Audio Capture Service (Tasks 4.1 - 4.6)

final class AudioCaptureService {

    /// Emits completed audio segments (post-VAD silence detection)
    let audioSegmentPublisher = PassthroughSubject<AudioSegment, Never>()
    /// Emits current RMS level 0..1 for waveform display
    let levelPublisher = PassthroughSubject<Float, Never>()
    /// 录音会话结束时发出，携带本次会话完整音频和时间边界
    let sessionEndPublisher = PassthroughSubject<RecordingSessionData, Never>()

    /// 当前录音会话累积的 PCM 样本（所有 VAD 段依次追加）
    private var sessionSamples: [Float] = []

    private let engine = AVAudioEngine()
    private var converter: AVAudioConverter?
    private let ringBuffer = AudioRingBuffer()           // 30min capacity
    private let vadDetector = VADDetector()
    private var sessionStartedAt: Date?

    private weak var appState: AppState?
    private var cancellables = Set<AnyCancellable>()

    // Whisper requires 16kHz mono
    private let targetFormat = AVAudioFormat(
        commonFormat: .pcmFormatFloat32,
        sampleRate: 16000,
        channels: 1,
        interleaved: false
    )!

    init(appState: AppState) {
        self.appState = appState

        // Propagate overflow warning to AppState (Task 4.5)
        ringBuffer.overflowPublisher
            .receive(on: DispatchQueue.main)
            .sink { [weak appState] in
                Task { @MainActor in
                    appState?.bufferWarning = true
                }
            }
            .store(in: &cancellables)

        // Hook VAD segment-complete → publish AudioSegment + 累积会话样本
        vadDetector.onSegmentComplete = { [weak self] samples in
            guard let self else { return }
            let segment = AudioSegment(samples: samples, capturedAt: Date())
            self.audioSegmentPublisher.send(segment)
            self.sessionSamples.append(contentsOf: samples)
        }
    }

    // MARK: - Start / Stop

    func start(completion: @escaping (AudioCaptureError?) -> Void) {
        // Task 4.6 - check/request microphone permission
        AVCaptureDevice.requestAccess(for: .audio) { [weak self] granted in
            if granted {
                DispatchQueue.main.async {
                    do {
                        try self?.startEngine()
                        self?.sessionStartedAt = Date()
                        completion(nil)
                    } catch let err as AudioCaptureError {
                        completion(err)
                    } catch {
                        completion(.engineStartFailed(error.localizedDescription))
                    }
                }
            } else {
                DispatchQueue.main.async {
                    completion(.permissionDenied)
                }
            }
        }
    }

    func stop() {
        engine.inputNode.removeTap(onBus: 0)
        engine.stop()

        // 先强制刷新 VAD 中尚未完成的语音段，确保短时录音也能保存
        vadDetector.forceFlush()

        // Flush remaining samples as final segment
        let remaining = ringBuffer.drainAll()
        if !remaining.isEmpty {
            let segment = AudioSegment(samples: remaining, capturedAt: Date())
            audioSegmentPublisher.send(segment)
            sessionSamples.append(contentsOf: remaining)
        }

        // 发出完整会话样本供持久化，然后清空缓冲
        let completedSession = sessionSamples
        if !completedSession.isEmpty {
            let startedAt = sessionStartedAt ?? Date().addingTimeInterval(-Double(completedSession.count) / 16000.0)
            sessionEndPublisher.send(
                RecordingSessionData(
                    samples: completedSession,
                    startedAt: startedAt,
                    endedAt: Date()
                )
            )
        }
        sessionSamples.removeAll()
        sessionStartedAt = nil

        vadDetector.reset()
        ringBuffer.reset()

        DispatchQueue.main.async { [weak self] in
            self?.appState?.audioLevel = 0
        }
    }

    // MARK: - Engine Setup

    private func startEngine() throws {
        let inputNode = engine.inputNode
        let inputFormat = inputNode.outputFormat(forBus: 0)

        // Setup converter: input → 16kHz mono float32 (Task 4.3)
        guard let conv = AVAudioConverter(from: inputFormat, to: targetFormat) else {
            throw AudioCaptureError.converterSetupFailed
        }
        self.converter = conv

        // Task 4.2 - install tap with 1024 frame buffer
        inputNode.installTap(onBus: 0, bufferSize: 1024, format: inputFormat) { [weak self] buffer, _ in
            self?.processTapBuffer(buffer)
        }

        engine.prepare()
        do {
            try engine.start()
        } catch {
            throw AudioCaptureError.engineStartFailed(error.localizedDescription)
        }
    }

    // MARK: - Buffer Processing

    private func processTapBuffer(_ inputBuffer: AVAudioPCMBuffer) {
        guard let converter,
              let outputBuffer = AVAudioPCMBuffer(
                pcmFormat: targetFormat,
                frameCapacity: AVAudioFrameCount(
                    Double(inputBuffer.frameLength) * targetFormat.sampleRate / inputBuffer.format.sampleRate + 1
                )
              ) else { return }

        var error: NSError?
        var inputConsumed = false

        // Task 4.3 - convert to 16kHz mono
        converter.convert(to: outputBuffer, error: &error) { _, outStatus in
            if inputConsumed {
                outStatus.pointee = .noDataNow
                return nil
            }
            outStatus.pointee = .haveData
            inputConsumed = true
            return inputBuffer
        }

        guard error == nil, outputBuffer.frameLength > 0,
              let channelData = outputBuffer.floatChannelData else { return }

        let samples = Array(UnsafeBufferPointer(
            start: channelData[0],
            count: Int(outputBuffer.frameLength)
        ))

        // Compute RMS for waveform display
        let rms = computeRMS(samples)
        DispatchQueue.main.async { [weak self] in
            self?.appState?.audioLevel = rms
        }

        // Feed into VAD detector
        vadDetector.feed(samples: samples)
    }

    // MARK: - Helpers

    private func computeRMS(_ samples: [Float]) -> Float {
        guard !samples.isEmpty else { return 0 }
        let sumSq = samples.reduce(0) { $0 + $1 * $1 }
        return min(1.0, sqrt(sumSq / Float(samples.count)) * 10)
    }
}

import Foundation
import FluidAudio

@available(macOS 14.0, *)
actor FluidAudioDiarizationService {
    private let manager: OfflineDiarizerManager
    private var isPrepared = false

    init(config: OfflineDiarizerConfig = OfflineDiarizerConfig()) {
        self.manager = OfflineDiarizerManager(config: config)
    }

    func buildTranscript(
        recordingURL: URL,
        transcriptionEntries: [TranscriptionEntry],
        session: RecordingSessionData
    ) async throws -> SpeakerAttributedTranscriptDocument? {
        guard !transcriptionEntries.isEmpty else { return nil }

        try await prepareIfNeeded()
        let result = try await manager.process(recordingURL)

        let diarizationSegments = result.segments.map {
            SpeakerDiarizationSegment(
                speakerLabel: $0.speakerId,
                startTimeSeconds: Double($0.startTimeSeconds),
                endTimeSeconds: Double($0.endTimeSeconds),
                qualityScore: $0.qualityScore
            )
        }

        let chunks = transcriptionEntries.map { entry in
            let relativeTimeSeconds = relativeTime(for: entry, in: session)
            let matchedSegment = bestSegment(for: relativeTimeSeconds, segments: diarizationSegments)

            return SpeakerAttributedTranscriptChunk(
                text: entry.text,
                timestamp: entry.timestamp,
                relativeTimeSeconds: relativeTimeSeconds,
                speakerLabel: matchedSegment?.speakerLabel,
                startTimeSeconds: matchedSegment?.startTimeSeconds,
                endTimeSeconds: matchedSegment?.endTimeSeconds
            )
        }

        let fullText = chunks.map(\.text).joined(separator: "\n")
        return SpeakerAttributedTranscriptDocument(
            fullText: fullText,
            chunks: chunks,
            diarizationSegments: diarizationSegments,
            engineMetadata: SpeechEngineMetadata(
                asrEngine: "whisper.cpp",
                diarizationEngine: "FluidAudio"
            )
        )
    }

    private func prepareIfNeeded() async throws {
        guard !isPrepared else { return }
        try await manager.prepareModels()
        isPrepared = true
    }

    private func relativeTime(for entry: TranscriptionEntry, in session: RecordingSessionData) -> Double {
        let sessionDuration = max(session.duration, 0.1)
        let raw = entry.timestamp.timeIntervalSince(session.startedAt)
        return min(max(raw, 0), sessionDuration)
    }

    private func bestSegment(
        for relativeTimeSeconds: Double,
        segments: [SpeakerDiarizationSegment]
    ) -> SpeakerDiarizationSegment? {
        guard !segments.isEmpty else { return nil }

        if let containing = segments.first(where: { $0.contains(timeSeconds: relativeTimeSeconds) }) {
            return containing
        }

        return segments.min {
            distance(from: relativeTimeSeconds, to: $0) < distance(from: relativeTimeSeconds, to: $1)
        }
    }

    private func distance(from time: Double, to segment: SpeakerDiarizationSegment) -> Double {
        if segment.contains(timeSeconds: time) { return 0 }
        if time < segment.startTimeSeconds { return segment.startTimeSeconds - time }
        return time - segment.endTimeSeconds
    }
}

import Foundation
import Combine

// MARK: - Transcription Service
// Receives AudioSegments, queues them for serial whisper.cpp transcription,
// and publishes results back to AppState.
// Subscribes to appState.$selectedModel for runtime hot-switching.

final class TranscriptionService {

    // Published: model ready / error (wired in AppDelegate)
    let modelReadyPublisher = PassthroughSubject<Bool, Never>()
    let modelErrorPublisher = PassthroughSubject<String, Never>()

    private let appState: AppState
    let modelManager: WhisperModelManager

    // Serial queue: prevents concurrent whisper inference
    private let transcriptionQueue = OperationQueue()

    private var cancellables = Set<AnyCancellable>()

    init(appState: AppState, modelManager: WhisperModelManager) {
        self.appState = appState
        self.modelManager = modelManager

        transcriptionQueue.maxConcurrentOperationCount = 1
        transcriptionQueue.qualityOfService = .userInitiated

        observeModelState()
        // 订阅需在 MainActor 上（appState 是 @MainActor 隔离）
        Task { @MainActor [weak self] in self?.observeSelectedModel() }
    }

    // MARK: - Lifecycle

    func start() {
        // 初始加载由 selectedModel 订阅驱动（observeSelectedModel dropFirst 已去掉），
        // 此处保留向后兼容：首次 start() 触发初始模型加载
        Task { [weak self] in
            guard let self else { return }
            let model = await MainActor.run { self.appState.selectedModel }
            NSLog("[TranscriptionService] start() 调用，加载模型: %@", model.rawValue)
            await self.modelManager.ensureModel(model)
        }
    }

    func stop() {
        transcriptionQueue.cancelAllOperations()
    }

    func waitUntilIdle() async {
        await withCheckedContinuation { continuation in
            transcriptionQueue.addBarrierBlock {
                continuation.resume()
            }
        }

        // `handleResult` appends entries on MainActor via Task; hop back once so pending
        // UI-state mutations triggered by finished operations are observed before snapshotting.
        await MainActor.run {}
    }

    // MARK: - Enqueue Segment

    func enqueue(_ segment: AudioSegment) {
        // switchModel 会先将 whisperContext 置 nil，切换期间此 guard 自然丢弃入队
        guard modelManager.whisperContext != nil else {
            NSLog("[TranscriptionService] 模型切换中，丢弃音频段")
            return
        }

        let op = TranscriptionOperation(
            segment: segment,
            context: modelManager.whisperContext!
        ) { [weak self] result in
            self?.handleResult(result, capturedAt: segment.capturedAt)
        }

        transcriptionQueue.addOperation(op)
    }

    // MARK: - Result Handler

    private func handleResult(_ result: Result<String, Error>, capturedAt: Date) {
        switch result {
        case .success(let text) where !text.isEmpty:
            let entry = TranscriptionEntry(
                text: text,
                timestamp: capturedAt,
                duration: 0
            )
            Task { @MainActor [weak self] in
                self?.appState.appendEntry(entry)
            }
        case .failure(let error):
            print("[TranscriptionService] Error: \(error)")
        default:
            break // empty transcription, skip
        }
    }

    // MARK: - Model State Observation

    private func observeModelState() {
        modelManager.statePublisher
            .sink { [weak self] state in
                switch state {
                case .ready:
                    self?.modelReadyPublisher.send(true)
                case .failed(let error):
                    self?.modelReadyPublisher.send(false)
                    self?.modelErrorPublisher.send(error.localizedDescription)
                    // 下载/加载失败时回退 selectedModel 到上一个成功的 activeModel
                    Task { @MainActor [weak self] in
                        guard let self,
                              let fallback = self.modelManager.activeModel else { return }
                        NSLog("[TranscriptionService] 模型加载失败，回退到 %@", fallback.rawValue)
                        self.appState.selectedModel = fallback
                    }
                default:
                    break
                }
            }
            .store(in: &cancellables)
    }

    /// 订阅 selectedModel 变化，触发热切换（必须在 @MainActor 上调用）
    @MainActor
    private func observeSelectedModel() {
        appState.$selectedModel
            .removeDuplicates()
            .dropFirst() // 跳过初始值，避免与 start() 重复加载
            .sink { [weak self] newModel in
                guard let self else { return }
                NSLog("[TranscriptionService] selectedModel 变化，切换到: %@", newModel.rawValue)
                self.transcriptionQueue.cancelAllOperations()
                Task { [weak self] in
                    await self?.modelManager.switchModel(newModel)
                }
            }
            .store(in: &cancellables)
    }
}

// MARK: - Transcription Operation

private final class TranscriptionOperation: Operation, @unchecked Sendable {
    private let segment: AudioSegment
    private let whisperContext: WhisperContext
    private let completion: (Result<String, Error>) -> Void

    init(segment: AudioSegment, context: WhisperContext, completion: @escaping (Result<String, Error>) -> Void) {
        self.segment = segment
        self.whisperContext = context
        self.completion = completion
    }

    override func main() {
        guard !isCancelled else { return }

        do {
            let text = try whisperContext.transcribe(samples: segment.samples)
            completion(.success(text))
        } catch {
            completion(.failure(error))
        }
    }
}

