import Foundation
import VoicePepperCore

// MARK: - CLI Argument Parser

struct CLIArgs {
    let wavPath: String
    let lang: String
    let whisperKitModel: String
    let noSpeaker: Bool

    static func parse() -> CLIArgs? {
        var args = CommandLine.arguments.dropFirst()
        var wavPath: String? = nil
        var lang = "zh"
        var whisperKitModel = "large-v3"
        var noSpeaker = false

        while !args.isEmpty {
            let arg = args.removeFirst()
            switch arg {
            case "--wav":
                guard let next = args.first else { printUsage(); return nil }
                args = args.dropFirst()
                wavPath = next
            case "--lang":
                guard let next = args.first else { printUsage(); return nil }
                args = args.dropFirst()
                lang = next
            case "--whisperkit-model":
                guard let next = args.first else { printUsage(); return nil }
                args = args.dropFirst()
                whisperKitModel = next
            case "--no-speaker":
                noSpeaker = true
            default:
                fputs("未知参数: \(arg)\n", stderr)
                printUsage()
                return nil
            }
        }

        guard let path = wavPath else {
            fputs("缺少必填参数 --wav\n", stderr)
            printUsage()
            return nil
        }

        return CLIArgs(wavPath: path, lang: lang, whisperKitModel: whisperKitModel, noSpeaker: noSpeaker)
    }

    private static func printUsage() {
        fputs("""
        Usage: VoicePepperEval --wav <path> [--lang zh|en] [--whisperkit-model <name>] [--no-speaker]

        Options:
          --wav <path>              WAV 文件路径（16kHz mono）
          --lang <zh|en>            转录语言（默认 zh）
          --whisperkit-model <name> WhisperKit 模型名称（默认 large-v3）
          --no-speaker              禁用 SpeakerKit（仅 ASR）

        """, stderr)
    }
}

// MARK: - Output Model

struct TranscriptChunkOutput: Codable {
    let text: String
    let start: Double
    let end: Double
    let speaker: String?
}

// MARK: - Pipeline Runner

func runPipeline(args: CLIArgs) async -> [TranscriptChunkOutput] {
    let wavURL = URL(fileURLWithPath: args.wavPath)

    guard FileManager.default.fileExists(atPath: args.wavPath) else {
        fputs("错误: 文件不存在 \(args.wavPath)\n", stderr)
        exit(1)
    }

    let asrService = WhisperKitASRService(modelName: args.whisperKitModel, language: args.lang)
    let speakerService: SpeakerKitDiarizationService? = args.noSpeaker ? nil : SpeakerKitDiarizationService()
    let merger = TimelineMerger()
    let fileSource = AudioFileSource()

    // 预热 WhisperKit 模型
    fputs("[VoicePepperEval] 正在加载 WhisperKit 模型...\n", stderr)
    await asrService.prepareModel()
    fputs("[VoicePepperEval] 模型就绪\n", stderr)

    // 连接 ASR 回调 → TimelineMerger
    await asrService.setCallback { event in
        Task {
            _ = await merger.applyASREvent(event, source: .filePlayback)
        }
    }

    // 连接 SpeakerKit 回调 → TimelineMerger
    if let sk = speakerService {
        await sk.setCallback { events in
            Task {
                for event in events {
                    _ = await merger.applySpeakerEvent(event)
                }
            }
        }
    }

    // 连接 AudioFileSource → ASR + Speaker
    var cancellables = [any Sendable]()
    let audioTask = Task {
        for await segment in fileSource.audioSegmentPublisher.values {
            await asrService.enqueue(segment)
            if let sk = speakerService {
                await sk.enqueue(segment)
            }
        }
    }

    // 播放文件（阻塞到 sessionEnd）
    fputs("[VoicePepperEval] 开始处理: \(args.wavPath)\n", stderr)
    await fileSource.play(url: wavURL, chunkDuration: 15.0)
    audioTask.cancel()

    // 等待所有正在进行的 ASR/Speaker 任务完成（简单等待）
    try? await Task.sleep(nanoseconds: 2_000_000_000)

    // 获取最终结果
    let chunks = await merger.snapshot()
    return chunks.map { chunk in
        TranscriptChunkOutput(
            text: chunk.text,
            start: chunk.startTimeSeconds,
            end: chunk.endTimeSeconds,
            speaker: chunk.speakerLabel
        )
    }
}

// MARK: - Entry Point

guard let args = CLIArgs.parse() else {
    exit(1)
}

let result = await runPipeline(args: args)

let encoder = JSONEncoder()
encoder.outputFormatting = [.prettyPrinted]
if let jsonData = try? encoder.encode(result),
   let jsonStr = String(data: jsonData, encoding: .utf8) {
    print(jsonStr)
} else {
    fputs("错误: JSON 序列化失败\n", stderr)
    exit(1)
}

