37	    private var cancellables = Set<AnyCancellable>()
38	    /// 手动管理偏好设置窗口，避免 .accessory app 中 showSettingsWindow: 不可靠的问题
39	    private var preferencesWindow: NSWindow?
40	
41	    // MARK: Lifecycle
42	
43	    func applicationWillFinishLaunching(_ notification: Notification) {
44	        terminatePreviousInstances()
45	    }
46	
47	    func applicationDidFinishLaunching(_ notification: Notification) {
48	        // Configure as agent (LSUIElement=YES in Info.plist handles dock hiding)
49	        NSApp.setActivationPolicy(.accessory)
