58	
59	    func applicationWillTerminate(_ notification: Notification) {
60	        audioCaptureService?.stop()
61	        bleRecorderService?.stopRealtimeTranscription()
62	        transcriptionService?.stop()
63	        // ggml-metal 析构链在 exit() 路径上会触发 GGML_ASSERT 并卡入 UE 状态；
64	        // _exit() 跳过 C++ 析构，由内核直接回收所有 GPU/文件资源，安全可靠。
65	        _exit(0)
66	    }
67	
68	    // MARK: Single Instance
69	
70	    /// 终止同名旧实例，确保同一时刻只有一个 VoicePepper 运行。
71	    /// 策略：先发 SIGTERM 优雅退出，2 秒后若仍存在则 SIGKILL 强杀。
72	    private func terminatePreviousInstances() {
73	        let myPID = ProcessInfo.processInfo.processIdentifier
74	        let myName = ProcessInfo.processInfo.processName
75	
76	        let stale = NSWorkspace.shared.runningApplications.filter {
77	            $0.processIdentifier != myPID && $0.localizedName == myName
78	        }
79	
80	        guard !stale.isEmpty else { return }
81	
82	        for app in stale {
83	            let pid = app.processIdentifier
84	            NSLog("[AppDelegate] 终止旧实例 PID=\(pid)")
85	            // 直接 SIGKILL：跳过 ggml-metal 析构路径，避免旧实例卡入 UE 状态
86	            kill(pid, SIGKILL)
87	        }
88	
89	        // 等待 OS 回收旧实例资源（status bar 槽位、Metal 上下文等）
90	        Thread.sleep(forTimeInterval: 1.0)
91	    }
92	
93	    // MARK: Setup
94	
95	    private func setupServices() {
96	        let audioService = AudioCaptureService(appState: appState)
97	        let transcriptionSvc = TranscriptionService(appState: appState, modelManager: modelManager)
98	
99	        audioCaptureService = audioService
100	        transcriptionService = transcriptionSvc
101	
102	        // 注入 RecordingFileService 到 AppState
103	        appState.recordingFileService = recordingFileService
104	        recordingFileService.loadRecordings()
105	
106	        if appState.speechPipelineMode == .experimentalArgmaxOSS {
107	            let wkService = WhisperKitASRService()
108	            let skService = SpeakerKitDiarizationService()
109	            let merger = TimelineMerger()
110	            experimentalWhisperKitService = wkService
111	            experimentalSpeakerKitService = skService
112	            timelineMerger = merger
113	            NSLog("[AppDelegate] Experimental speech pipeline enabled: WhisperKit + SpeakerKit")
114	            // 注入模型加载状态回调 → AppState
115	            Task {
116	                await wkService.setModelReadyCallback { [weak self] ready, status in
117	                    Task { @MainActor [weak self] in
118	                        self?.appState.isWhisperKitModelReady = ready
119	                        self?.appState.whisperKitModelStatus = status
120	                    }
121	                }
122	            }
123	            // 立即触发模型下载/预热，避免首次录音时懒加载造成延迟
124	            Task { await wkService.prepareModel() }
125	            // 注入 WhisperKit 转录回调 → TimelineMerger → AppState.realtimeChunks
126	            Task {
127	                await wkService.setCallback { [weak self] event in
128	                    Task { @MainActor [weak self] in
129	                        self?.handleWhisperKitASREvent(event)
130	                    }
131	                }
132	            }
133	            // 注入 SpeakerKit diarization 回调 → TimelineMerger → AppState.realtimeChunks
134	            Task {
135	                await skService.setCallback { [weak self] events in
136	                    Task { @MainActor [weak self] in
137	                        guard let self else { return }
138	                        for event in events {
139	                            let chunks = await merger.applySpeakerEvent(event)
140	                            self.appState.updateRealtimeChunks(chunks)
141	                        }
142	                    }
143	                }
144	            }
145	        }
146	
147	        // Start model loading immediately on launch
148	        transcriptionSvc.start()
149	
150	        // E2E 测试钩子：允许 SwiftUI 按钮通过 AppState 触发录音
